#!/usr/bin/env python3
"""Regenerate controller_parity.json from the Python and JS reference controllers.

Run from the repo root:

    python3 games/tbd/tests/fixtures/gen_parity.py

Needs numpy (the Python reference imports it) and Node, for tbd_control.js.
"""
import json
import math
import pathlib
import subprocess
import sys

ROOT = pathlib.Path(__file__).resolve().parents[4]
sys.path.insert(0, str(ROOT / "assets" / "tbd" / "reference"))
from tbd_control import Battery, FlightController, mix, quat_to_rpy, wrap  # noqa: E402

OUT = pathlib.Path(__file__).resolve().parent / "controller_parity.json"


def rpy_to_quat(roll, pitch, yaw):
    cr, sr = math.cos(roll / 2), math.sin(roll / 2)
    cp, sp = math.cos(pitch / 2), math.sin(pitch / 2)
    cy, sy = math.cos(yaw / 2), math.sin(yaw / 2)
    return [
        cr * cp * cy + sr * sp * sy,
        sr * cp * cy - cr * sp * sy,
        cr * sp * cy + sr * cp * sy,
        cr * cp * sy - sr * sp * cy,
    ]


def seq(name, dt, steps, a_ff=(0, 0, 0)):
    fc = FlightController()
    out_steps = []
    for s in steps:
        pos, quat, vel, omega, p_des, v_des, yaw_des = s
        u, f = fc.step(dt, pos, quat, vel, omega, p_des, v_des, yaw_des, a_ff)
        out_steps.append(
            {
                "pos": list(map(float, pos)),
                "quat": list(map(float, quat)),
                "vel": list(map(float, vel)),
                "omega": list(map(float, omega)),
                "p_des": list(map(float, p_des)),
                "v_des": list(map(float, v_des)),
                "yaw_des": float(yaw_des),
                "python": {
                    "u": [float(x) for x in u],
                    "f": [float(x) for x in f],
                    "rpy": [float(x) for x in quat_to_rpy(quat)],
                },
            }
        )
    return {"name": name, "dt": dt, "a_ff": list(map(float, a_ff)), "steps": out_steps}


def main():
    q_tilt = rpy_to_quat(0.1, -0.15, 0.4)
    q_yaw = rpy_to_quat(0.0, 0.0, 3.0)
    ident = [1, 0, 0, 0]
    z = [0, 0, 0]
    cases = [
        seq(
            "hover",
            0.002,
            [([0, 0, 1], ident, z, z, [0, 0, 1], z, 0.0)] * 3,
        ),
        seq(
            "offset",
            0.002,
            [
                (
                    [0.3, -0.2, 0.4],
                    q_tilt,
                    [0.1, -0.05, 0.2],
                    [0.2, -0.1, 0.3],
                    [0, 0, 1],
                    [0.2, 0, 0.5],
                    0.2,
                )
            ]
            * 5,
        ),
        seq(
            "saturation",
            0.002,
            [([-5, 4, 0], ident, z, z, [0, 0, 1], z, 0.0)] * 2,
        ),
        seq(
            "yaw_wrap",
            0.002,
            [([0, 0, 1], q_yaw, z, [0, 0, 0.4], [0, 0, 1], z, -3.0)] * 2,
        ),
        seq(
            "feedforward",
            0.002,
            [([0, 0, 0.5], ident, z, z, [0, 0, 1], z, 0.0)] * 2,
            a_ff=(1.0, -0.5, 0.25),
        ),
    ]
    mixes = []
    for F, tx, ty, tz in [(9.5157, 0.0, 0.0, 0.0), (8.0, 0.01, -0.02, 0.005), (30.0, 0.2, 0.2, 0.05)]:
        mixes.append(
            {
                "F": F,
                "tx": tx,
                "ty": ty,
                "tz": tz,
                "python": [float(x) for x in mix(F, tx, ty, tz)],
            }
        )
    wraps = []
    for a in [0.0, 0.5, -0.5, 3.5, -4.0, math.pi, -math.pi, 7.0]:
        wraps.append({"a": a, "python": float(wrap(a))})
    quats = []
    for q in [ident, q_tilt, q_yaw, rpy_to_quat(-0.4, 0.2, 1.2)]:
        quats.append({"q": q, "python": [float(x) for x in quat_to_rpy(q)]})
    bat = Battery()
    thrusts = [0.970 * 9.81 / 4.0] * 4
    battery_steps = []
    for i in range(8):
        driving = 1.0 if i == 7 else 0.0
        power = float(bat.power(thrusts, driving))
        pct = float(bat.step(0.002, thrusts, driving))
        battery_steps.append(
            {"thrusts": thrusts, "driving": driving, "python_power": power, "python_pct": pct}
        )
    doc = {
        "note": "Generated by gen_parity.py from assets/tbd/reference. Physics sim with estimated parameters.",
        "controller": cases,
        "mix": mixes,
        "wrap": wraps,
        "quat": quats,
        "battery": {"dt": 0.002, "hover_minutes": float(bat.hover_minutes()), "steps": battery_steps},
    }
    # JS reference has no a_ff; the node helper fills js fields for a_ff == 0.
    raw = json.dumps(doc)
    js = subprocess.check_output(
        ["node", str(pathlib.Path(__file__).resolve().parent / "fill_js_parity.mjs")],
        input=raw.encode(),
    )
    OUT.write_bytes(js)
    print(f"wrote {OUT}")


if __name__ == "__main__":
    main()
